CREATE TABLE IF NOT EXISTS zones (id INTEGER PRIMARY KEY AUTOINCREMENT, detected_at INTEGER NOT NULL, last_updated INTEGER NOT NULL, symbol TEXT NOT NULL, price_low REAL NOT NULL, price_high REAL NOT NULL, zone_type TEXT NOT NULL, source TEXT NOT NULL, timeframe TEXT NOT NULL, score REAL NOT NULL DEFAULT 0, tier TEXT NOT NULL DEFAULT 'noise', status TEXT NOT NULL DEFAULT 'active', factors_json TEXT NOT NULL DEFAULT '{}', invalidation_price REAL, notes TEXT);
CREATE INDEX IF NOT EXISTS idx_zones_active ON zones(symbol, status, tier, score DESC);
CREATE TABLE IF NOT EXISTS zone_touches (id INTEGER PRIMARY KEY AUTOINCREMENT, zone_id INTEGER NOT NULL REFERENCES zones(id), ts INTEGER NOT NULL, price REAL NOT NULL, reaction TEXT, timeframe TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at INTEGER NOT NULL, zone_id INTEGER REFERENCES zones(id), alert_type TEXT NOT NULL, condition_json TEXT NOT NULL, triggered_at INTEGER, triggered_price REAL, delivered_via TEXT, delivery_status TEXT, dedupe_key TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_alerts_dedupe ON alerts(dedupe_key);
CREATE TABLE IF NOT EXISTS setups (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at INTEGER NOT NULL, zone_id INTEGER NOT NULL REFERENCES zones(id), direction TEXT NOT NULL, entry_price REAL NOT NULL, stop_price REAL NOT NULL, target1_price REAL NOT NULL, target2_price REAL, rr_to_t1 REAL NOT NULL, rr_to_t2 REAL, confidence REAL NOT NULL, reaction_type TEXT NOT NULL, trigger_type TEXT NOT NULL, status TEXT NOT NULL, closed_at INTEGER, realised_r REAL, notes_json TEXT);
CREATE INDEX IF NOT EXISTS idx_setups_status ON setups(status, created_at DESC);
CREATE TABLE IF NOT EXISTS reports (id INTEGER PRIMARY KEY AUTOINCREMENT, generated_at INTEGER NOT NULL, report_date TEXT NOT NULL UNIQUE, bias TEXT NOT NULL, btc_price REAL NOT NULL, markdown_body TEXT NOT NULL, chart_paths_json TEXT);
CREATE TABLE IF NOT EXISTS indicator_snapshots (symbol TEXT NOT NULL, timeframe TEXT NOT NULL, bar_time INTEGER NOT NULL, rsi14 REAL, macd REAL, macd_signal REAL, macd_hist REAL, atr14 REAL, ema21 REAL, ema50 REAL, ema100 REAL, ema200 REAL, sma200 REAL, PRIMARY KEY (symbol, timeframe, bar_time));
CREATE TABLE IF NOT EXISTS volume_profile_snapshots (snapshot_date TEXT NOT NULL, window TEXT NOT NULL, poc REAL NOT NULL, vah REAL NOT NULL, val REAL NOT NULL, profile_json TEXT NOT NULL, PRIMARY KEY (snapshot_date, window));
CREATE TABLE IF NOT EXISTS bot_log (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, level TEXT NOT NULL, component TEXT NOT NULL, message TEXT NOT NULL, context_json TEXT);
CREATE INDEX IF NOT EXISTS idx_bot_log_ts ON bot_log(ts DESC);
